const repo=path.resolve(__dirname,'..'),manifest=JSON.parse(fs.readFileSync('/private/tmp/seti-final-currency-20261119.json')),rt=manifest.runtime;
const name=process.argv[2];assert(['late','311','324','344'].includes(name));const input=path.join(repo,'reports/ai-foundation-20261119',name==='late'?'held-final-land-before-empty-launch-20261119-v1.json.gz':'autonomous-r4-resource-roots-20261119-v1.json.gz'),raw=JSON.parse(zlib.gunzipSync(fs.readFileSync(input))),envelope=(name==='late'?raw:raw.find(x=>x.beforeInput===Number(name))).envelope;
